const cases = [
  {
    case_id: 'case-001',
    expected_category: '[0] 網路/推流品質',
    expected_keywords: ['卡', '斷續', 'Poor CDN Connection'],
    evalConfig: { modelName: 'gemini-2.5-pro', temperature: 0.1 },
    aggregateData: [
      {
        liveStreamID: '213754852',
        details: [
          {
            liveStreamID: '213754852',
            type: 'dialogue',
            dialogue: '[21:04:10] [streamer]: 畫面有點卡\n[21:04:15] [viewer]: 聲音斷斷續續'
          },
          {
            liveStreamID: '213754852',
            type: 'streamerLog',
            conditions: [],
            filterLogs: [
              {
                conditionID: 'bitrate_fail',
                description: 'Bitrate CV > 0.3',
                lineNumber: 1,
                timestamp: '2025-12-21T21:04:15',
                dataSnippet: {
                  BitrateCV: '0.72',
                  PingMax: '999.0',
                  UnsentCountMax: '158.0',
                  NetworkType: 'WiFi'
                }
              }
            ]
          },
          {
            liveStreamID: '213754852',
            type: 'streamEventLog',
            conditions: [],
            filterLogs: [
              {
                lineNumber: 1,
                timestamp: '2025-12-21T21:04:12',
                title: 'Poor CDN Connection',
                Log: '{"time":"21:04:12","title":"Poor CDN Connection"}'
              }
            ]
          },
          {
            type: 'streamInfo',
            liveStreamID: '213754852',
            streamInfo: [
              {
                liveStreamID: '213754852',
                closeBy: 'normalEnd',
                deviceModel: 'iPhone 13',
                type: 'iOS',
                version: '3.260.0',
                ipRegion: 'JP'
              }
            ]
          }
        ],
        count: 4
      }
    ]
  },
  {
    case_id: 'case-002',
    expected_category: '[3] 無資料/無法判定',
    expected_keywords: ['無資料', '查無'],
    evalConfig: { modelName: 'gemini-3.0-pro-preview', temperature: 0.1 },
    aggregateData: []
  }
];

return cases.map((item) => ({ json: item }));

const item = $json;

function parseMaybeJson(value, fallback) {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(String(value));
  } catch {
    return fallback;
  }
}

const aggregateData = (() => {
  const parsed = parseMaybeJson(item.aggregateData, []);
  return Array.isArray(parsed) ? parsed : [];
})();

const evalConfigRaw = parseMaybeJson(item.evalConfig, {});
const evalConfig = {
  modelName: evalConfigRaw.modelName || 'gemini-3.0-pro-preview',
  temperature:
    typeof evalConfigRaw.temperature === 'number'
      ? evalConfigRaw.temperature
      : Number(evalConfigRaw.temperature ?? 0.1),
};

const expectedKeywords = (() => {
  if (Array.isArray(item.expected_keywords)) return item.expected_keywords;
  if (typeof item.expected_keywords === 'string') {
    return item.expected_keywords
      .split(',')
      .map((k) => k.trim())
      .filter(Boolean);
  }
  return [];
})();

return [{
  json: {
    case_id: item.case_id || `row-${item.row_number ?? 0}`,
    expected_category: String(item.expected_category || ''),
    expected_keywords: expectedKeywords,
    evalConfig,
    aggregateData,
    row_id: item.row_id,
    row_number: item.row_number,
  },
}];

const row = $json || {};
const summary = row.summary || {};
const report = summary.report || {};
const summaryBlock = report.summary || {};

const actualCategory = String(summaryBlock.responsibility_category || '').trim();
const expectedCategory = String(row.expected_category || '').trim();
const expectedKeywords = Array.isArray(row.expected_keywords) ? row.expected_keywords : [];

const categoryMatch = expectedCategory !== '' && actualCategory === expectedCategory ? 1 : 0;

const evaluatorOutput = $('AI Keyword Evaluator').first().json || {};
const evalResult = (() => {
  if (evaluatorOutput && typeof evaluatorOutput === 'object') {
    if (evaluatorOutput.keyword_hit !== undefined) return evaluatorOutput;
    if (evaluatorOutput.output && typeof evaluatorOutput.output === 'object' && evaluatorOutput.output.keyword_hit !== undefined) {
      return evaluatorOutput.output;
    }
    if (typeof evaluatorOutput.output === 'string') {
      try {
        return JSON.parse(evaluatorOutput.output);
      } catch {}
    }
  }
  return { keyword_hit: 0, hit_keywords: [] };
})();

const keywordHit = Number(evalResult.keyword_hit || 0) === 1 ? 1 : 0;
let hitKeywords = Array.isArray(evalResult.hit_keywords)
  ? evalResult.hit_keywords.map((k) => String(k)).filter((k) => expectedKeywords.includes(k))
  : [];

if (keywordHit === 1 && hitKeywords.length === 0) {
  hitKeywords = expectedKeywords;
}

const success = categoryMatch === 1 && keywordHit === 1 ? 1 : 0;

return [{
  json: {
    case_id: row.case_id || '',
    expected_category: expectedCategory,
    actual_category: actualCategory,
    expected_keywords: expectedKeywords,
    hit_keywords: hitKeywords,
    category_match: categoryMatch,
    keyword_hit: keywordHit,
    success,
    modelVersion: row.modelVersion || '',
    usageMetadata: row.usageMetadata || {},
    summary,
    row_id: row.row_id,
    row_number: row.row_number,
    keyword_eval_raw: evalResult,
  },
}];

const rows = $input.all().map((i) => i.json);
const total = rows.length;
const successCount = rows.reduce((acc, row) => acc + Number(row.success || 0), 0);
const categoryMatchCount = rows.reduce((acc, row) => acc + Number(row.category_match || 0), 0);
const keywordHitCount = rows.reduce((acc, row) => acc + Number(row.keyword_hit || 0), 0);

return [{
  json: {
    total,
    successCount,
    successRate: total > 0 ? successCount / total : 0,
    categoryMatchCount,
    categoryMatchRate: total > 0 ? categoryMatchCount / total : 0,
    keywordHitCount,
    keywordHitRate: total > 0 ? keywordHitCount / total : 0,
    rows,
  },
}];

